#include <stdint.h>

const uint8_t mask = 0x01;

void setup() {
  uint8_t cppValue = 0x0F;
  cppValue ^= mask;  // переносимый результат C++: 0x0E

  uint8_t asmValue = 0x0F;
  // Inline-ассемблер AVR-GCC; не переносим на все платы Arduino.
  asm volatile (
    "eor %0, %1"
    : "+r" (asmValue)  // выход: чтение и запись в регистре
    : "r" (mask)       // вход: mask находится в регистре
    : "cc"              // EOR изменяет флаги условий
  );                  // asmValue также равен 0x0E
  Serial.begin(9600);
  Serial.print(cppValue);
  Serial.print(' ');
  Serial.println(asmValue);  // только вывод примера; не измеряйте Serial
}

void loop() {}
